package com.example;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("fishingcounter")
public interface FishingCounterConfig extends Config
{
	@ConfigSection(
			name = "Toggle Visibility",
			description = "Check the boxes of the fish you want to see in the overlay.",
			position = 0
	)
	String visibilitySection = "visibility";

	@ConfigSection(
			name = "Sharks Settings",
			description = "Configuration for Sharks.",
			position = 10
	)
	String sharkSection = "sharkSection";

	@ConfigSection(
			name = "Bass Settings",
			description = "Configuration for Bass.",
			position = 20
	)
	String bassSection = "bassSection";

	@ConfigSection(
			name = "Swordfish Settings",
			description = "Configuration for Swordfish.",
			position = 30
	)
	String swordfishSection = "swordfishSection";

	@ConfigSection(
			name = "Tuna Settings",
			description = "Configuration for Tuna.",
			position = 40
	)
	String tunaSection = "tunaSection";

	@ConfigItem(
			keyName = "fishData",
			name = "Fish Data",
			description = "Internal database storage.",
			hidden = true
	)
	default String fishData()
	{
		return "";
	}

	@ConfigItem(
			keyName = "showLuck",
			name = "Show Luck % (Dry Calc)",
			description = "Displays the cumulative statistical probability of having received a Big Fish drop.",
			position = 1
	)
	default boolean showLuck()
	{
		return true;
	}

	// --- SEZIONE VISIBILITÀ ---
	@ConfigItem(
			keyName = "showShark",
			name = "Track Sharks",
			description = "Check to display sharks in your overlay.",
			position = 2,
			section = visibilitySection
	)
	default boolean showShark()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showBass",
			name = "Track Bass",
			description = "Check to display bass in your overlay.",
			position = 3,
			section = visibilitySection
	)
	default boolean showBass()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showSwordfish",
			name = "Track Swordfish",
			description = "Check to display swordfish in your overlay.",
			position = 4,
			section = visibilitySection
	)
	default boolean showSwordfish()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showTuna",
			name = "Track Tuna",
			description = "Check to display tuna in your overlay.",
			position = 5,
			section = visibilitySection
	)
	default boolean showTuna()
	{
		return true;
	}

	// --- SHARKS ---
	@ConfigItem(
			keyName = "sharkStartKc",
			name = "Shark Start KC",
			description = "Starting value for sharks.",
			position = 11,
			section = sharkSection
	)
	default int sharkStartKc()
	{
		return 0;
	}

	@ConfigItem(
			keyName = "resetSharkButton",
			name = "Reset Shark KC",
			description = "Check to wipe saved Shark data for the active game mode.",
			position = 12,
			section = sharkSection
	)
	default boolean resetSharkButton()
	{
		return false;
	}

	// --- BASS ---
	@ConfigItem(
			keyName = "bassStartKc",
			name = "Bass Start KC",
			description = "Starting value for bass.",
			position = 21,
			section = bassSection
	)
	default int bassStartKc()
	{
		return 0;
	}

	@ConfigItem(
			keyName = "resetBassButton",
			name = "Reset Bass KC",
			description = "Check to wipe saved Bass data for the active game mode.",
			position = 22,
			section = bassSection
	)
	default boolean resetBassButton()
	{
		return false;
	}

	// --- SWORDFISH ---
	@ConfigItem(
			keyName = "swordfishStartKc",
			name = "Swordfish Start KC",
			description = "Starting value for swordfish.",
			position = 31,
			section = swordfishSection
	)
	default int swordfishStartKc()
	{
		return 0;
	}

	@ConfigItem(
			keyName = "resetSwordfishButton",
			name = "Reset Swordfish KC",
			description = "Check to wipe saved Swordfish data for the active game mode.",
			position = 32,
			section = swordfishSection
	)
	default boolean resetSwordfishButton()
	{
		return false;
	}

	// --- TUNA ---
	@ConfigItem(
			keyName = "tunaStartKc",
			name = "Tuna Start KC",
			description = "Starting value for tuna.",
			position = 41,
			section = tunaSection
	)
	default int tunaStartKc()
	{
		return 0;
	}

	@ConfigItem(
			keyName = "resetTunaButton",
			name = "Reset Tuna KC",
			description = "Check to wipe saved Tuna data for the active game mode.",
			position = 42,
			section = tunaSection
	)
	default boolean resetTunaButton()
	{
		return false;
	}
}

package com.example;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Map;
import java.util.TreeMap;
import java.util.HashMap;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class FishingCounterOverlay extends OverlayPanel
{
    private final FishingCounterPlugin plugin;
    private final FishingCounterConfig config;

    @Inject
    public FishingCounterOverlay(FishingCounterPlugin plugin, FishingCounterConfig config)
    {
        setPosition(OverlayPosition.TOP_LEFT);
        this.plugin = plugin;
        this.config = config;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Map<String, Integer> currentCounts = plugin.getCurrentModeMap();
        if (currentCounts == null)
        {
            currentCounts = new HashMap<>();
        }

        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(TitleComponent.builder()
                .text("Fishing Counter (" + plugin.getCurrentGameMode() + ")")
                .build());

        Map<String, Integer> displayMap = new TreeMap<>();

        if (config.showShark())
        {
            displayMap.put("shark", currentCounts.getOrDefault("shark", 0) + config.sharkStartKc());
        }
        if (config.showBass())
        {
            displayMap.put("bass", currentCounts.getOrDefault("bass", 0) + config.bassStartKc());
        }
        if (config.showSwordfish())
        {
            displayMap.put("swordfish", currentCounts.getOrDefault("swordfish", 0) + config.swordfishStartKc());
        }
        if (config.showTuna())
        {
            displayMap.put("tuna", currentCounts.getOrDefault("tuna", 0) + config.tunaStartKc());
        }

        for (Map.Entry<String, Integer> entry : currentCounts.entrySet())
        {
            String fish = entry.getKey();
            if (!displayMap.containsKey(fish) && isFishEnabled(fish))
            {
                displayMap.put(fish, entry.getValue() + plugin.getBonusKc(fish));
            }
        }

        if (displayMap.isEmpty())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("No fish selected")
                    .right("")
                    .build());
            return super.render(graphics);
        }

        for (Map.Entry<String, Integer> entry : displayMap.entrySet())
        {
            String fish = entry.getKey();
            int totalCount = entry.getValue();

            String leftText = fish.substring(0, 1).toUpperCase() + fish.substring(1);

            if (config.showLuck())
            {
                double luckPercent = calculateLuckPercentage(fish, totalCount);
                if (luckPercent > 0.0)
                {
                    leftText += String.format(" (%.1f%% Luck)", luckPercent);
                }
            }

            panelComponent.getChildren().add(LineComponent.builder()
                    .left(leftText)
                    .right(String.valueOf(totalCount))
                    .build());
        }

        return super.render(graphics);
    }

    private double calculateLuckPercentage(String fishName, int kc)
    {
        if (kc <= 0) return 0.0;

        double dropRate = 0.0;
        switch (fishName.toLowerCase())
        {
            case "bass":
                dropRate = 1.0 / 1000.0;
                break;
            case "swordfish":
                dropRate = 1.0 / 2500.0;
                break;
            case "shark":
                dropRate = 1.0 / 5000.0;
                break;
            default:
                return 0.0;
        }

        double chanceOfNoDrop = Math.pow(1.0 - dropRate, kc);
        double luckChance = 1.0 - chanceOfNoDrop;

        return luckChance * 100.0;
    }

    private boolean isFishEnabled(String fishName)
    {
        switch (fishName.toLowerCase())
        {
            case "shark": return config.showShark();
            case "bass": return config.showBass();
            case "swordfish": return config.showSwordfish();
            case "tuna": return config.showTuna();
            default: return true;
        }
    }
}

package com.example;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;

@Slf4j
@PluginDescriptor(
		name = "Fishing Counter Ultimate",
		description = "Tracks fish with multi-mode isolation, individual fish resets, luck tracker, and checkboxes.",
		tags = {"fishing", "counter", "leagues", "overlay", "persist", "luck"}
)
public class FishingCounterPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private FishingCounterConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private FishingCounterOverlay overlay;

	@Inject
	private Gson gson;

	private final Map<String, Map<String, Integer>> multiModeFishCounts = new HashMap<>();

	@Override
	protected void startUp() throws Exception
	{
		multiModeFishCounts.clear();
		loadSessionData();
		overlayManager.add(overlay);
		log.info("Fishing Counter Ultimate started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		log.info("Fishing Counter Ultimate stopped!");
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		String message = chatMessage.getMessage();

		if (message != null && (message.startsWith("You catch a") || message.startsWith("You catch some")))
		{
			String fishName = parseFishName(message).toLowerCase();
			String currentMode = getCurrentGameMode();

			Map<String, Integer> currentModeMap = multiModeFishCounts.computeIfAbsent(currentMode, k -> new HashMap<>());
			currentModeMap.put(fishName, currentModeMap.getOrDefault(fishName, 0) + 1);

			saveSessionData();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals("fishingcounter"))
		{
			return;
		}

		String currentMode = getCurrentGameMode();
		Map<String, Integer> currentModeMap = multiModeFishCounts.get(currentMode);

		if (currentModeMap == null)
		{
			return;
		}

		boolean changed = false;

		// Verifica se l'interruttore è stato attivato, effettua il reset e deseleziona la casella
		if (event.getKey().equals("resetSharkButton") && config.resetSharkButton())
		{
			currentModeMap.remove("shark");
			changed = true;
			configManager.setConfiguration("fishingcounter", "resetSharkButton", "false");
			log.info("[Fishing Tracker] Reset Sharks for mode: " + currentMode);
		}
		else if (event.getKey().equals("resetBassButton") && config.resetBassButton())
		{
			currentModeMap.remove("bass");
			changed = true;
			configManager.setConfiguration("fishingcounter", "resetBassButton", "false");
			log.info("[Fishing Tracker] Reset Bass for mode: " + currentMode);
		}
		else if (event.getKey().equals("resetSwordfishButton") && config.resetSwordfishButton())
		{
			currentModeMap.remove("swordfish");
			changed = true;
			configManager.setConfiguration("fishingcounter", "resetSwordfishButton", "false");
			log.info("[Fishing Tracker] Reset Swordfish for mode: " + currentMode);
		}
		else if (event.getKey().equals("resetTunaButton") && config.resetTunaButton())
		{
			currentModeMap.remove("tuna");
			changed = true;
			configManager.setConfiguration("fishingcounter", "resetTunaButton", "false");
			log.info("[Fishing Tracker] Reset Tuna for mode: " + currentMode);
		}

		if (changed)
		{
			saveSessionData();
		}
	}

	public Map<String, Integer> getCurrentModeMap()
	{
		return multiModeFishCounts.get(getCurrentGameMode());
	}

	public int getBonusKc(String fishName)
	{
		try
		{
			String key = fishName.toLowerCase() + "StartKc";
			Integer bonus = configManager.getConfiguration("fishingcounter", key, Integer.class);
			return bonus != null ? bonus : 0;
		}
		catch (Exception e)
		{
			return 0;
		}
	}

	public String getCurrentGameMode()
	{
		if (client == null || client.getWorldType() == null) return "MAIN";
		EnumSet<WorldType> types = client.getWorldType();

		if (types.contains(WorldType.SEASONAL)) return "LEAGUES";
		if (types.contains(WorldType.DEADMAN)) return "DEADMAN";

		return "MAIN";
	}

	private String parseFishName(String message)
	{
		String cleaned = message.replace("You catch a ", "")
				.replace("You catch some ", "")
				.replace("raw ", "")
				.replace(".", "")
				.replace("!", "")
				.trim();

		if (cleaned.startsWith("an "))
		{
			cleaned = cleaned.substring(3);
		}
		return cleaned;
	}

	private void saveSessionData()
	{
		String json = gson.toJson(multiModeFishCounts);
		configManager.setConfiguration("fishingcounter", "fishData", json);
	}

	private void loadSessionData()
	{
		String json = configManager.getConfiguration("fishingcounter", "fishData");
		if (json != null && !json.isEmpty())
		{
			Type type = new TypeToken<Map<String, Map<String, Integer>>>(){}.getType();
			Map<String, Map<String, Integer>> loadedData = gson.fromJson(json, type);
			if (loadedData != null)
			{
				multiModeFishCounts.putAll(loadedData);
			}
		}
	}

	@Provides
	FishingCounterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FishingCounterConfig.class);
	}
}

package com.example;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ExamplePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(FishingCounterPlugin.class);
		RuneLite.main(args);
	}
}
